diff --git a/internal/hosted/agent/trace.go b/internal/hosted/agent/trace.go
new file mode 100644
index 0000000..54bb987
--- /dev/null
+++ b/internal/hosted/agent/trace.go
@@ -0,0 +1,98 @@
+package agent
+
+import (
+	"context"
+	"sync"
+	"time"
+	"unicode/utf8"
+
+	"px1/internal/hosted/review"
+)
+
+// Trace records every model call, tool call, and task outcome of one agentic
+// review, in order, for the report's "How px1 reviewed this" section. It is
+// safe for concurrent sub-agents and bounded: events past MaxTraceEvents are
+// counted, not stored.
+type Trace struct {
+	revision string
+	tier     Tier
+	now      func() time.Time
+
+	mu      sync.Mutex
+	events  []review.TraceEvent
+	dropped int
+}
+
+func NewTrace(revision string, tier Tier, now func() time.Time) *Trace {
+	if now == nil {
+		now = time.Now
+	}
+	return &Trace{revision: revision, tier: tier, now: now}
+}
+
+// Dispatch runs a tool call through box and records it. Linked-issue content
+// is never copied into the trace: reports can be published more widely than
+// the tracker it came from.
+func (t *Trace) Dispatch(ctx context.Context, box Toolbox, scope Scope, agent string, call Call) (Result, error) {
+	started := t.now()
+	result, err := box.Dispatch(ctx, scope, call)
+	event := review.TraceEvent{Agent: agent, Kind: "tool", Name: call.Name, Detail: clipTrace(string(call.Arguments), review.MaxTraceDetailBytes), ElapsedMS: t.now().Sub(started).Milliseconds()}
+	if err != nil {
+		event.Failed = true
+	} else {
+		event.ResultBytes, event.Truncated = len(result.Content), result.Truncated
+		if call.Name != ReadIssue {
+			event.Preview = clipTrace(result.Content, review.MaxTracePreview)
+		}
+	}
+	t.add(event)
+	return result, err
+}
+
+// Model records one model call for a role ("planner", "judge", or a
+// sub-agent's change-group ID) with its settled token usage.
+func (t *Trace) Model(agent, role string, inputTokens, outputTokens int64, failed bool, elapsed time.Duration) {
+	t.add(review.TraceEvent{Agent: agent, Kind: "model", Name: role, InputTokens: inputTokens, OutputTokens: outputTokens, Failed: failed, ElapsedMS: elapsed.Milliseconds()})
+}
+
+func (t *Trace) task(p Partial) {
+	t.add(review.TraceEvent{Agent: p.BlockID, Kind: "task", Name: string(p.Outcome), Detail: p.Reason, Failed: p.Outcome != TaskCompleted})
+}
+
+func (t *Trace) add(event review.TraceEvent) {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	if len(t.events) >= review.MaxTraceEvents {
+		t.dropped++
+		return
+	}
+	event.Seq = len(t.events) + 1
+	t.events = append(t.events, event)
+}
+
+// File snapshots the trace with the meter's final spend.
+func (t *Trace) File(spend Spend) review.TraceFile {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	return review.TraceFile{
+		Revision: t.revision,
+		Tier:     string(t.tier),
+		Spend: review.TraceSpend{
+			InputTokens: spend.InputTokens, OutputTokens: spend.OutputTokens, CostMicrousd: spend.CostMicrousd,
+			ModelCalls: spend.ModelCalls, ToolCalls: spend.ToolCalls, Exhausted: spend.Exhausted,
+		},
+		Events:  append([]review.TraceEvent{}, t.events...),
+		Dropped: t.dropped,
+	}
+}
+
+func clipTrace(value string, limit int) string {
+	if len(value) <= limit {
+		return value
+	}
+	cut := limit - len("…")
+	for cut > 0 && !utf8.RuneStart(value[cut]) {
+		cut--
+	}
+	return value[:cut] + "…"
+}

diff --git a/internal/hosted/agent/trace_test.go b/internal/hosted/agent/trace_test.go
new file mode 100644
index 0000000..21cc867
--- /dev/null
+++ b/internal/hosted/agent/trace_test.go
@@ -0,0 +1,85 @@
+package agent
+
+import (
+	"context"
+	"encoding/json"
+	"strings"
+	"sync"
+	"testing"
+	"time"
+
+	"px1/internal/hosted/review"
+)
+
+func TestTraceRecordsToolCallsWithoutIssueContent(t *testing.T) {
+	trace := NewTrace(scope.HeadSHA, Plus, nil)
+	box := Toolbox{Files: &fakeFiles{}, Issues: &fakeIssues{}}
+	if _, err := trace.Dispatch(context.Background(), box, scope, "g1", call(ReadFile, `{"path":"a.go","start_line":1,"end_line":2}`)); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := trace.Dispatch(context.Background(), box, scope, "g1", call(ReadIssue, `{"key":"ENG-12"}`)); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := trace.Dispatch(context.Background(), box, scope, "g1", call(ReadFile, `{"path":"../x","start_line":1,"end_line":2}`)); err == nil {
+		t.Fatal("escape accepted")
+	}
+	trace.Model("g1", "sub-agent", 120, 30, false, time.Second)
+	file := trace.File(Spend{ModelCalls: 1, ToolCalls: 3})
+	if len(file.Events) != 4 || file.Events[0].Seq != 1 || file.Events[3].Seq != 4 {
+		t.Fatalf("events: %#v", file.Events)
+	}
+	read, issue, rejected := file.Events[0], file.Events[1], file.Events[2]
+	if !read.Truncated || read.ResultBytes == 0 || len(read.Preview) > review.MaxTracePreview || read.Preview == "" {
+		t.Fatalf("read event: %#v", read)
+	}
+	if issue.Preview != "" || issue.ResultBytes == 0 {
+		t.Fatalf("issue content leaked into the trace: %#v", issue)
+	}
+	if !rejected.Failed || rejected.Preview != "" {
+		t.Fatalf("rejected call: %#v", rejected)
+	}
+	data, _ := json.Marshal(file)
+	if _, err := review.DecodeTraceFile(data, scope.HeadSHA); err != nil {
+		t.Fatalf("recorder output must pass the report decoder: %v", err)
+	}
+}
+
+func TestTraceIsBoundedAndConcurrencySafe(t *testing.T) {
+	trace := NewTrace(scope.HeadSHA, Apex, nil)
+	var wg sync.WaitGroup
+	for i := 0; i < review.MaxTraceEvents+50; i++ {
+		wg.Add(1)
+		go func() { defer wg.Done(); trace.Model("judge", "judge", 1, 1, false, 0) }()
+	}
+	wg.Wait()
+	file := trace.File(Spend{})
+	if len(file.Events) != review.MaxTraceEvents || file.Dropped != 50 {
+		t.Fatalf("events=%d dropped=%d", len(file.Events), file.Dropped)
+	}
+	for i, event := range file.Events {
+		if event.Seq != i+1 {
+			t.Fatalf("event %d has seq %d", i, event.Seq)
+		}
+	}
+}
+
+func TestRunnerRecordsTaskOutcomes(t *testing.T) {
+	limiter, _ := NewOrgLimiter(2)
+	trace := NewTrace(scope.HeadSHA, Plus, nil)
+	runner := Runner{Limiter: limiter, Trace: trace, SubAgent: func(_ context.Context, task PlanTask, _ *Meter) ([]review.Finding, error) {
+		if task.BlockID == "bad" {
+			return nil, ErrToolCallLimit
+		}
+		return nil, nil
+	}}
+	if _, err := runner.Run(context.Background(), 7, tasksFor("ok", "bad"), NewMeter(runBudget(2, time.Minute), time.Now(), nil)); err != nil {
+		t.Fatal(err)
+	}
+	outcomes := map[string]review.TraceEvent{}
+	for _, event := range trace.File(Spend{}).Events {
+		outcomes[event.Agent] = event
+	}
+	if outcomes["ok"].Name != "completed" || outcomes["bad"].Name != "failed" || !strings.Contains(outcomes["bad"].Detail, "tool-call limit") {
+		t.Fatalf("task events: %#v", outcomes)
+	}
+}

